#include <stdio.h>

int main(void) {
    int N;
    scanf("%d", &N);

    int balance = 0;
    int valid = 1;
    int c;

    while ((c = getchar()) != EOF) {
        if (c == '{') {
            balance++;
        } else if (c == '}') {
            balance--;
            if (balance < 0) {
                valid = 0;
            }
        }
    }

    if (valid && balance == 0) {
        printf("S\n");
    } else {
        printf("N\n");
    }

    return 0;
}
